 </style></head><body><main id="game"><canvas id="view"></canvas><div class="vignette"></div><div class="grain"></div><div class="damage" id="damage"></div><div class="hud"><header class="topbar"><div><div class="brand">DEAD<span> SIGNAL</span></div><div class="eyebrow">Salvage Division // Field Unit 07</div></div><div class="raid-tag">ZONE 04 — <b>BLACKWATER</b><br><span class="eyebrow">DEPLOYMENT 06:42</span></div></header><section class="objective"><div class="label">PRIMARY OBJECTIVE</div><strong id="objective">Recover the cores</strong><small id="objective-sub">0 / 3 data cores secured</small></section><aside class="rightstack"><div class="threat">SIGNAL<b>● HOSTILE</b></div><div class="mapbox"><div class="maptitle">SECTOR MAP</div><canvas id="map"></canvas></div></aside><div class="crosshair"><i></i><i></i><i></i><i></i></div><div class="prompt" id="prompt"></div><div class="bottom"><div class="vitals"><div class="vital"><span class="stat-label">VITALS</span><b id="health">100</b><div class="bar red"><i id="healthbar"></i></div></div><div class="vital"><span class="stat-label">ARMOR</span><b id="armor">75</b><div class="bar"><i id="armorbar" style="width:75%"></i></div></div></div><div class="weapon"><div class="weapon-name">K-17 // RANGER</div><div class="weapon-meta">5.56 × 45 mm&nbsp; · &nbsp;SEMI-AUTO</div><div class="ammo"><span id="ammo">24</span><small> / 96</small></div></div></div><div class="help"><span class="key">W A S D</span> MOVE <span class="key">MOUSE</span> AIM <span class="key">CLICK</span> FIRE <span class="key">E</span> INTERACT <span class="key">R</span> RELOAD</div></div><div class="toast" id="toast"></div><div class="mobile-controls"><div class="move"><button data-key="w">▲</button><button data-key="a">◀</button><button data-key="s">▼</button><button data-key="d">▶</button></div><div style="display:flex;gap:10px;align-items:flex-end"><button id="mobile-use">USE</button><button id="mobile-fire">FIRE</button></div></div><div class="overlay" id="overlay"><div class="card"><div class="kicker">// EXTRACTION ZONE 04</div><h1>DEAD<br><span>SIGNAL</span></h1><p>The Blackwater relay went dark three nights ago. Recover the data cores, then make it to the extraction beacon. The scavengers already know you're here.</p><div class="brief"><div><b>03</b><span>DATA CORES</span></div><div><b>01</b><span>EXTRACTION</span></div><div><b>∞</b><span>THREATS</span></div></div><button class="primary" id="deploy">DEPLOY INTO BLACKWATER&nbsp; →</button><div class="fine">WASD to move · Mouse to aim · Click to fire · E to interact · R to reload</div></div></div></main>
 <script>
+const canvas=document.querySelector('#view'),ctx=canvas.getContext('2d'),mapCanvas=document.querySelector('#map'),mctx=mapCanvas.getContext('2d');
+const mapRows=['################','#..............#','#..#.....#.....#','#..#...........#','#......#.......#','#..............#','#....##........#','#..............#','#......#.......#','#..............#','#...........#..#','#..#...........#','#...............','#.......#......#','#..............#','################'];
+const W=mapRows[0].length,H=mapRows.length,wall=(x,y)=>x<0||y<0||x>=W||y>=H||mapRows[Math.floor(y)][Math.floor(x)]==='#';
+const player={x:2.5,y:2.5,a:.18,hp:100,armor:75,ammo:24,reserve:96,cores:0};
+const pickups=[{x:5.5,y:2.5,type:'core',name:'DATA CORE'},{x:12.5,y:5.5,type:'core',name:'DATA CORE'},{x:3.5,y:12.5,type:'core',name:'DATA CORE'},{x:7.5,y:4.5,type:'med',name:'FIELD DRESSING'},{x:10.5,y:12.5,type:'ammo',name:'AMMO CACHE'}];
+const exit={x:13.5,y:13.5};const enemies=[{x:10.5,y:3.5,hp:100,alive:true,cool:1.6},{x:8.5,y:9.5,hp:100,alive:true,cool:2.3},{x:4.5,y:9.5,hp:100,alive:true,cool:1.1}];
+let running=false,locked=false,last=0,elapsed=0,kick=0,flash=0,toastTimer=0,interactTarget=null,exitReady=false;
+const keys={};const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
+function resize(){const d=Math.min(devicePixelRatio||1,1.5);canvas.width=Math.floor(innerWidth*d);canvas.height=Math.floor(innerHeight*d);canvas.style.width=innerWidth+'px';canvas.style.height=innerHeight+'px';mapCanvas.width=mapCanvas.clientWidth*2;mapCanvas.height=mapCanvas.clientHeight*2}addEventListener('resize',resize);resize();
+function say(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),1900)}
+function distance(a,b){return Math.hypot(a.x-b.x,a.y-b.y)}
+function cast(angle){const dx=Math.cos(angle),dy=Math.sin(angle);let mx=Math.floor(player.x),my=Math.floor(player.y),ddx=Math.abs(1/(dx||1e-8)),ddy=Math.abs(1/(dy||1e-8)),sx=dx<0?-1:1,sy=dy<0?-1:1,sdx=(dx<0?player.x-mx:mx+1-player.x)*ddx,sdy=(dy<0?player.y-my:my+1-player.y)*ddy,side=0,steps=0;while(steps++<45){if(sdx<sdy){sdx+=ddx;mx+=sx;side=0}else{sdy+=ddy;my+=sy;side=1}if(wall(mx,my))break}let d=side?sdy-ddy:sdx-ddx;let hit=side?player.x+(d)*dx:player.y+(d)*dy;return{d:Math.max(.001,d),side,wall:side?hit-Math.floor(hit):hit-Math.floor(hit),mx,my}}
+function renderWorld(){const w=canvas.width,h=canvas.height;if(!w||!h)return;const sky=ctx.createLinearGradient(0,0,0,h*.53);sky.addColorStop(0,'#1a2420');sky.addColorStop(.72,'#536055');sky.addColorStop(1,'#858574');ctx.fillStyle=sky;ctx.fillRect(0,0,w,h*.53);const floor=ctx.createLinearGradient(0,h*.49,0,h);floor.addColorStop(0,'#4d5144');floor.addColorStop(.18,'#292e27');floor.addColorStop(1,'#111712');ctx.fillStyle=floor;ctx.fillRect(0,h*.49,w,h*.51);const fov=1.12,step=2;let depths=[];for(let x=0;x<w;x+=step){const ray=player.a+(x/w-.5)*fov,r=cast(ray),dist=r.d*Math.cos(ray-player.a);depths[x]=dist;const wh=Math.min(h*2,h/(dist*.75)),top=(h-wh)/2+kick*dist*.08;let shade=clamp(1-dist/14,.13,.86)*(r.side?.75:1),v=42+Math.floor(shade*87);ctx.fillStyle=`rgb(${Math.floor(v*.78)},${Math.floor(v*.9)},${Math.floor(v*.72)})`;ctx.fillRect(x,top,step+1,wh);let tx=(r.wall*9|0)%9;if(tx===0||tx===8){ctx.fillStyle=`rgba(9,14,10,${.35*shade})`;ctx.fillRect(x,top,step+1,wh)}const band=(Math.floor(top/17)+r.mx*3+r.my*5)%11;if(band===0){ctx.fillStyle=`rgba(172,174,132,${.14*shade})`;ctx.fillRect(x,top+wh*.23,step+1,2)}if(dist<5&&tx===4){ctx.fillStyle=`rgba(217,243,156,${.3*(1-dist/5)})`;ctx.fillRect(x,top+wh*.18,step,Math.max(3,wh*.16))}ctx.fillStyle=`rgba(0,0,0,${clamp(dist/15,.06,.65)})`;ctx.fillRect(x,top,step+1,wh);for(let y=top+wh;y<h;y+=Math.max(5,Math.round(y/h*12))){if(y>h*.55){ctx.fillStyle=`rgba(0,0,0,${.1*shade})`;ctx.fillRect(x,y,step,1)}}}
+renderEntities(w,h,fov,depths,step);renderWeapon(w,h)}
+function renderEntities(w,h,fov,depths,step){let list=[...pickups.filter(p=>!p.taken).map(p=>({...p,kind:p.type})),...enemies.filter(e=>e.alive).map(e=>({...e,kind:'enemy'})),{...exit,kind:'exit'}].map(o=>({...o,d:distance(player,o),ang:Math.atan2(o.y-player.y,o.x-player.x)})).sort((a,b)=>b.d-a.d);for(const o of list){let rel=Math.atan2(Math.sin(o.ang-player.a),Math.cos(o.ang-player.a));if(Math.abs(rel)>fov*.72||o.d<.2)continue;let sx=(.5+rel/fov)*w,sy=h/2+kick*o.d*.08,size=Math.min(h*1.1,h/(o.d*.8)),col=Math.max(0,Math.min(w-1,Math.floor(sx/step)*step));if(o.d>(depths[col]||99)+.25)continue;ctx.save();ctx.translate(sx,sy);if(o.kind==='enemy'){drawEnemy(size,o)}else if(o.kind==='core'||o.kind==='med'||o.kind==='ammo'){drawCrate(size,o)}else{drawExit(size,o)}ctx.restore()}}
+function drawEnemy(s,o){const body=s*.52,head=s*.15;ctx.globalAlpha=clamp(1-o.d/17,.2,1);ctx.fillStyle='#111712';ctx.beginPath();ctx.ellipse(0,s*.39,s*.28,s*.08,0,0,7);ctx.fill();ctx.fillStyle='#374139';ctx.fillRect(-body*.42,-s*.05,body*.84,s*.5);ctx.fillStyle='#555b4d';ctx.beginPath();ctx.arc(0,-s*.16,head,0,7);ctx.fill();ctx.fillStyle='#171d17';ctx.fillRect(-body*.58,-s*.02,body*.17,s*.38);ctx.fillRect(body*.41,-s*.02,body*.17,s*.38);ctx.fillStyle='#d5ff43';ctx.fillRect(-head*.65,-s*.18,head*1.3,Math.max(1,s*.018));if(o.hp<100){ctx.fillStyle='#111';ctx.fillRect(-s*.3,-s*.32,s*.6,3);ctx.fillStyle='#f35f49';ctx.fillRect(-s*.3,-s*.32,s*.6*o.hp/100,3)}ctx.globalAlpha=1}
+function drawCrate(s,o){const c=o.kind==='core'?'#d5ff43':o.kind==='med'?'#85d5ae':'#c69758';ctx.fillStyle='#0c100d';ctx.fillRect(-s*.2,s*.06,s*.4,s*.25);ctx.fillStyle='#424a3c';ctx.fillRect(-s*.18,-s*.08,s*.36,s*.22);ctx.fillStyle=c;ctx.fillRect(-s*.16,-s*.08,s*.32,s*.035);ctx.fillRect(-s*.035,-s*.01,s*.07,s*.12);ctx.fillStyle=c;ctx.globalAlpha=.13;ctx.beginPath();ctx.arc(0,0,s*.38,0,7);ctx.fill();ctx.globalAlpha=1}
+function drawExit(s){const blink=.5+.5*Math.sin(elapsed*3);ctx.strokeStyle=exitReady?`rgba(213,255,67,${.55+blink*.4})`:'rgba(242,95,73,.8)';ctx.lineWidth=Math.max(2,s*.035);ctx.beginPath();ctx.ellipse(0,s*.18,s*.32,s*.1,0,0,7);ctx.stroke();ctx.fillStyle=exitReady?'#d5ff43':'#f35f49';ctx.globalAlpha=.2+blink*.15;ctx.fillRect(-s*.28,-s*.6,s*.56,s*.78);ctx.globalAlpha=1;ctx.fillStyle=exitReady?'#d5ff43':'#f35f49';ctx.fillRect(-s*.035,-s*.58,s*.07,s*.64);ctx.fillRect(-s*.2,-s*.6,s*.4,Math.max(2,s*.04));ctx.fillStyle='#ddd';ctx.font=`${Math.max(8,s*.1)}px monospace`;ctx.textAlign='center';ctx.fillText('EXFIL',0,-s*.69)}
+function renderWeapon(w,h){let s=Math.min(w,h),x=w*.54+kick*2,y=h*.94;ctx.save();ctx.translate(x,y);ctx.rotate(-.08);ctx.fillStyle='#181d18';ctx.beginPath();ctx.moveTo(-s*.03,0);ctx.lineTo(-s*.02,-s*.2);ctx.lineTo(s*.17,-s*.22);ctx.lineTo(s*.19,-s*.12);ctx.lineTo(s*.1,-s*.08);ctx.lineTo(s*.07,0);ctx.fill();ctx.fillStyle='#353b32';ctx.fillRect(-s*.015,-s*.26,s*.22,s*.065);ctx.fillStyle='#202720';ctx.fillRect(s*.03,-s*.31,s*.16,s*.06);ctx.fillStyle='#59604e';ctx.fillRect(s*.13,-s*.29,s*.07,s*.025);ctx.fillStyle='#111611';ctx.fillRect(s*.1,-s*.37,s*.12,s*.075);ctx.fillStyle='#6d745d';ctx.fillRect(s*.12,-s*.35,s*.08,s*.02);ctx.fillStyle='#242a22';ctx.fillRect(s*.025,-s*.21,s*.04,s*.09);ctx.restore();if(flash>0){ctx.fillStyle=`rgba(255,215,100,${flash})`;ctx.beginPath();ctx.arc(w*.68,h*.7,s*.035,0,7);ctx.fill()}}
+function drawMap(){const w=mapCanvas.width,h=mapCanvas.height,s=Math.min(w/W,h/H);mctx.clearRect(0,0,w,h);mctx.fillStyle='#111811';mctx.fillRect(0,0,w,h);for(let y=0;y<H;y++)for(let x=0;x<W;x++){mctx.fillStyle=wall(x,y)?'#576050':'#20291f';mctx.fillRect(x*s,y*s,s-1,s-1)}for(const p of pickups)if(!p.taken){mctx.fillStyle=p.type==='core'?'#d5ff43':'#b8c5a5';mctx.fillRect(p.x*s-2,p.y*s-2,4,4)}mctx.fillStyle='#f35f49';mctx.fillRect(exit.x*s-3,exit.y*s-3,6,6);for(const e of enemies)if(e.alive){mctx.fillStyle='#f35f49';mctx.beginPath();mctx.arc(e.x*s,e.y*s,2.4,0,7);mctx.fill()}mctx.save();mctx.translate(player.x*s,player.y*s);mctx.rotate(player.a);mctx.fillStyle='#d5ff43';mctx.beginPath();mctx.moveTo(6,0);mctx.lineTo(-4,-3);mctx.lineTo(-4,3);mctx.fill();mctx.restore()}

