function update(dt){elapsed+=dt;if(!running)return;const sp=3.1*dt,rot=2.2*dt;let f=(keys.w||keys.arrowup?1:0)-(keys.s||keys.arrowdown?1:0),side=(keys.d?1:0)-(keys.a?1:0);if(keys.arrowleft)player.a-=rot;if(keys.arrowright)player.a+=rot;let dx=Math.cos(player.a)*f*sp+Math.cos(player.a+Math.PI/2)*side*sp,dy=Math.sin(player.a)*f*sp+Math.sin(player.a+Math.PI/2)*side*sp;if(!wall(player.x+dx+.19*Math.sign(dx),player.y))player.x+=dx;if(!wall(player.x,player.y+dy+.19*Math.sign(dy)))player.y+=dy;kick=Math.max(0,kick-dt*18);flash=Math.max(0,flash-dt*5);for(const e of enemies){if(!e.alive)continue;const d=distance(e,player),a=Math.atan2(player.y-e.y,player.x-e.x);if(d>3.1&&d<12){const vx=Math.cos(a)*dt*.48,vy=Math.sin(a)*dt*.48;if(!wall(e.x+vx,e.y))e.x+=vx;if(!wall(e.x,e.y+vy))e.y+=vy}e.cool-=dt;if(d<8&&e.cool<=0){e.cool=1.5+Math.random()*1.7;if(Math.abs(Math.atan2(Math.sin(a-player.a),Math.cos(a-player.a)))<1.6){player.armor=Math.max(0,player.armor-10);if(player.armor<=0)player.hp=Math.max(0,player.hp-9);document.querySelector('#damage').classList.add('hit');setTimeout(()=>document.querySelector('#damage').classList.remove('hit'),120);ui();if(player.hp<=0)finish(false)}}}findTarget();if(player.cores===3&&!exitReady){exitReady=true;document.querySelector('#objective').textContent='Reach extraction';document.querySelector('#objective-sub').textContent='Beacon active — make it out';say('ALL CORES SECURED // EXTRACTION BEACON ACTIVE')}ui()}
function findTarget(){let best=null,bd=1.8;for(const p of pickups){if(p.taken)continue;const d=distance(p,player);if(d<bd){best=p;bd=d}}const de=distance(exit,player);if(de<2.1&&(!best||de<bd)){best={...exit,kind:'exit'};bd=de}interactTarget=best;const el=document.querySelector('#prompt');if(best){el.classList.add('show');el.textContent=best.kind==='exit'?(exitReady?'[ E ]  EXTRACT':'[ E ]  EXTRACTION LOCKED — SECURE CORES'):`[ E ]  ${best.name}`}else el.classList.remove('show')}
function interact(){if(!running||!interactTarget)return;const t=interactTarget;if(t.kind==='exit'){if(!exitReady){say('EXTRACTION LOCKED // SECURE 3 DATA CORES');return}finish(true);return}t.taken=true;if(t.type==='core'){player.cores++;say('DATA CORE SECURED // '+player.cores+' / 3');document.querySelector('#objective-sub').textContent=`${player.cores} / 3 data cores secured`}else if(t.type==='med'){player.hp=Math.min(100,player.hp+30);say('FIELD DRESSING // VITALS RESTORED')}else{player.reserve+=30;say('AMMO CACHE // +30 ROUNDS')}ui()}
function fire(){if(!running)return;if(player.ammo<=0){say('MAGAZINE EMPTY // PRESS R');return}player.ammo--;kick=9;flash=.8;let target=null,best=.095;for(const e of enemies){if(!e.alive)continue;const a=Math.atan2(e.y-player.y,e.x-player.x),off=Math.abs(Math.atan2(Math.sin(a-player.a),Math.cos(a-player.a))),d=distance(e,player);if(off<best&&d<13){const old=player.a;player.a=a;const sight=cast(a).d;player.a=old;if(sight>d-.3){target=e;best=off}}}if(target){target.hp-=50;say(target.hp<=0?'SCAVENGER DOWN':'TARGET HIT');if(target.hp<=0)target.alive=false}ui()}
function reload(){if(player.ammo>=24||player.reserve<=0)return;const n=Math.min(24-player.ammo,player.reserve);player.ammo+=n;player.reserve-=n;say('RELOADED // '+player.reserve+' IN RESERVE');ui()}
function ui(){document.querySelector('#health').textContent=player.hp;document.querySelector('#armor').textContent=player.armor;document.querySelector('#healthbar').style.width=player.hp+'%';document.querySelector('#armorbar').style.width=player.armor/75*100+'%';document.querySelector('#ammo').textContent=player.ammo;document.querySelector('.ammo small').textContent=' / '+player.reserve}
