document.querySelector('#deploy').addEventListener('click',()=>{running=true;document.querySelector('#overlay').classList.add('hidden');canvas.requestPointerLock?.()});document.addEventListener('pointerlockchange',()=>locked=document.pointerLockElement===canvas);document.addEventListener('mousemove',e=>{if(locked&&running)player.a+=e.movementX*.0024});document.addEventListener('mousedown',e=>{if(running&&e.button===0)fire()});document.addEventListener('keydown',e=>{const k=e.key.toLowerCase();keys[k]=true;if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();if(k==='e')interact();if(k==='r')reload();if(k==='escape'&&running&&!locked)say('CLICK TO AIM // ESC TO RELEASE MOUSE')});document.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);canvas.addEventListener('click',()=>{if(running&&!locked)canvas.requestPointerLock?.()});document.querySelectorAll('[data-key]').forEach(b=>{const k=b.dataset.key;b.addEventListener('pointerdown',e=>{e.preventDefault();keys[k]=true});['pointerup','pointerleave','pointercancel'].forEach(ev=>b.addEventListener(ev,()=>keys[k]=false))});document.querySelector('#mobile-use').addEventListener('pointerdown',interact);document.querySelector('#mobile-fire').addEventListener('pointerdown',fire);let touchX=null;canvas.addEventListener('touchstart',e=>{touchX=e.touches[0].clientX},{passive:true});canvas.addEventListener('touchmove',e=>{if(touchX!==null){player.a+=(e.touches[0].clientX-touchX)*.006;touchX=e.touches[0].clientX}},{passive:true});
